import test from 'node:test';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';import {mkdtempSync,mkdirSync,writeFileSync,rmSync,symlinkSync} from 'node:fs';import {tmpdir} from 'node:os';import {join} from 'node:path';import {forwardBaselineSource,readMigrationTrees} from './forward-baseline.mjs';
function fixture(){const repository=mkdtempSync(join(tmpdir(),'aihr-forward-baseline-'));const git=(...args)=>execFileSync('git',args,{cwd:repository,encoding:'utf8',stdio:['pipe','pipe','pipe']}).trim();mkdirSync(join(repository,'db/migrations/meta'),{recursive:true});git('init','-q');git('config','user.name','Private fixture');git('config','user.email','fixture@example.invalid');let rows=[];const commit=()=>{writeFileSync(join(repository,'db/migrations/meta/_journal.json'),JSON.stringify({entries:rows}));git('add','.');git('commit','-qm','fixture');return git('rev-parse','HEAD');};const add=(tag,when)=>{rows.push({idx:rows.length,version:'7',when,tag,breakpoints:true});writeFileSync(join(repository,'db/migrations/'+tag+'.sql'),'select '+when+';');return commit();};const ciBaseline=add('first',10),deploymentBaseline=add('second',20),candidate=add('third',30);return {repository,git,rows,commit,add,ciBaseline,deploymentBaseline,candidate,close:()=>rmSync(repository,{recursive:true,force:true})};}
test('forward descendant keeps original CI baseline and binds exact intermediate source',()=>{const f=fixture();try{const p=forwardBaselineSource(f);assert.equal(p.ciBaseline,f.ciBaseline);assert.equal(p.deploymentMigrationCount,2);assert.equal(p.candidateMigrationCount,3);assert.equal(p.releaseAuthorized,false);}finally{f.close();}});
test('same staging baseline remains a source proof, never an execution waiver',()=>{const f=fixture();try{const p=forwardBaselineSource({...f,deploymentBaseline:f.ciBaseline});assert.equal(p.deploymentMigrationCount,1);assert(p.requiresFreshActualLedgerAndBuildBinding);}finally{f.close();}});
for(const [name,change] of [
 ['rewritten applied SQL',f=>writeFileSync(join(f.repository,'db/migrations/first.sql'),'select 999;')],
 ['changed historical journal timestamp',f=>f.rows[0].when=99],
 ['reordered prefix',f=>f.rows.reverse()],
 ['removed prefix',f=>f.rows.shift()],
])test('refuses '+name,()=>{const f=fixture();try{change(f);const candidate=f.commit();assert.throws(()=>forwardBaselineSource({...f,candidate}));}finally{f.close();}});
test('refuses reverse/divergent and symbolic baseline identities',()=>{const f=fixture();try{assert.throws(()=>forwardBaselineSource({...f,ciBaseline:f.candidate,deploymentBaseline:f.ciBaseline}));assert.throws(()=>forwardBaselineSource({...f,ciBaseline:'HEAD'}));}finally{f.close();}});

test('batch refuses symlink migration inputs',()=>{const f=fixture();try{const path=join(f.repository,'db/migrations/third.sql');rmSync(path);symlinkSync('first.sql',path);const candidate=f.commit();assert.throws(()=>forwardBaselineSource({...f,candidate}),/regular blob/);}finally{f.close();}});
test('batch refuses missing journal-listed SQL',()=>{const f=fixture();try{rmSync(join(f.repository,'db/migrations/third.sql'));const candidate=f.commit();assert.throws(()=>forwardBaselineSource({...f,candidate}),/immutable SQL/);}finally{f.close();}});
test('batch rejects symbolic or unbounded input refs',()=>{assert.throws(()=>readMigrationTrees('.', ['HEAD']),/Exact bounded/);assert.throws(()=>readMigrationTrees('.', []),/Exact bounded/);});
